            "code": "```java
private String handleNull(final String input)  {
    final boolean isQuoted = reusableToken.isQuoted;
    final String nullString = format.getNullString();
    final boolean strictQuoteMode = isStrictQuoteMode();
    if (input.equals(nullString))
    {
        // nullString = NULL(String), distinguish between "NULL" and NULL in ALL_NON_NULL or NON_NUMERIC quote mode return strictQuoteMode && isQuoted ? input : null;
    }
    // don't set nullString, distinguish between "" and ,, (absent values) in All_NON_NULL or NON_NUMERIC quote mode return strictQuoteMode && nullString == null && input.isEmpty() && !isQuoted ? null : input;
}
