CSVRecord nextRecord() throws IOException  {
    CSVRecord result = null;
    recordList.clear();
    StringBuilder sb = null;
    final long startCharPosition = lexer.getCharacterPosition() + characterOffset;
    final long startBytePosition = lexer.getBytesRead() + characterOffset;
    do
    {
        reusableToken.reset();
        lexer.nextToken(reusableToken);
        switch (reusableToken.type)
        {
            case TOKEN: addRecordValue(false);
            break;
            case EORECORD: addRecordValue(true);
            break;
            case EOF: if (reusableToken.isReady)
            {
                addRecordValue(true);
            }
            else if (sb != null)
            {
                trailerComment = sb.toString();
            }
            break;
            case INVALID: throw new CSVException("(line %,d) invalid parse sequence", getCurrentLineNumber());
            case COMMENT: // Ignored currently if (sb == null)
            {
                // first comment for this record sb = new StringBuilder();
            }
            else
            {
                sb.append(Constants.LF);
            }
            sb.append(reusableToken.content);
            reusableToken.type = TOKEN;
            // Read another token break;
            default: throw new CSVException("Unexpected Token type: %s", reusableToken.type);
        }
    }
    while (reusableToken.type == TOKEN);
    if (!recordList.isEmpty())
    {
        recordNumber++;
        result = new CSVRecord(this, recordList.toArray(Constants.EMPTY_STRING_ARRAY), Objects.toString(sb, null), recordNumber, startCharPosition, startBytePosition);
    }
    return result;
}
