public ImmutableNode removeChild(final ImmutableNode child)  {
    // use same size of children in case the child does not exist final Builder builder = new Builder(children.size(), attributes);
    boolean foundChild = false;
    for (final ImmutableNode c : children)
    {
        if (c == child)
        {
            foundChild = true;
        }
        else
        {
            builder.addChild(c);
        }
    }
    return foundChild ? createWithBasicProperties(builder) : this;
}
