                observedMissing |= blankHeader;
                if (header != null)
                {
                    headerMap.put(header, Integer.valueOf(i));
                    // Explicit (un)boxing is intentional if (headerNames == null)
                    {
                        headerNames = new ArrayList<>(headerRecord.length);
                    }
                    headerNames.add(header);
                }
            }
        }
    }
    // Make header names Collection immutable return new Headers(headerMap, headerNames == null ? Collections.emptyList() : Collections.unmodifiableList(headerNames));
