public int read(final char[] buf, final int offset, final int length) throws IOException  {
    if (length == 0)
    {
        return 0;
    }
    final int len = super.read(buf, offset, length);
    if (len > 0)
    {
        for (int i = offset;
        i < offset + len;
        i++)
        {
            final char ch = buf[i];
            if (ch == LF)
            {
                if (CR != (i > offset ? buf[i - 1] : lastChar))
                {
                    lineNumber++;
                }
            }
            else if (ch == CR)
            {
                lineNumber++;
            }
        }
        lastChar = buf[offset + len - 1];
    }
    else if (len == EOF)
    {
        lastChar = EOF;
    }
    position += len;
    return len;
}
