            case INVALID: throw new CSVException("(line %,d) invalid parse sequence", getCurrentLineNumber());
            case COMMENT: // Ignored currently if (sb == null)
            {
                // first comment for this record sb = new StringBuilder();
            }
            else
            {
                sb.append(Constants.LF);
