    if (!sql.equals(lastValidationSql))
    {
        lastValidationSql = sql;
        // Has to be the innermost delegate else the prepared statement will // be closed when the pooled connection is passivated. validationPreparedStatement = getInnermostDelegateInternal().prepareStatement(sql);
    }
    if (timeoutDuration.compareTo(Duration.ZERO) > 0)
    {
        validationPreparedStatement.setQueryTimeout((int) timeoutDuration.getSeconds());
    }
    try (ResultSet rs = validationPreparedStatement.executeQuery())
    {
        if (!rs.next())
        {
            throw new SQLException("validationQuery didn't return a row");
        }
    }
    catch (final SQLException sqle)
