boolean isDisconnectionSqlException(final SQLException e)  {
    boolean fatalException = false;
    final String sqlState = e.getSQLState();
    if (sqlState != null)
    {
        if (disconnectionIgnoreSqlCodes != null && disconnectionIgnoreSqlCodes.contains(sqlState))
        {
            return false;
        }
        fatalException = disconnectionSqlCodes == null ? sqlState.startsWith(Utils.DISCONNECTION_SQL_CODE_PREFIX) || Utils.isDisconnectionSqlCode(sqlState) : disconnectionSqlCodes.contains(sqlState);
    }
    return fatalException;
}
