public void close() throws SQLException  {
    lock.lock();
    try
    {
        if (isClosedInternal())
        {
            // already closed return;
        }
        boolean isUnderlyingConnectionClosed;
        try
        {
            isUnderlyingConnectionClosed = getDelegateInternal().isClosed();
        }
        catch (final SQLException e)
        {
            try
            {
                pool.invalidateObject(this);
            }
            catch (final IllegalStateException ise)
            {
                // pool is closed, so close the connection passivate();
                getInnermostDelegate().close();
            }
            catch (final Exception ignored)
            {
                // DO NOTHING the original exception will be rethrown
            }
            throw new SQLException("Cannot close connection (isClosed check failed)", e);
        }
        /* * Can't set close before this code block since the connection needs to be open when validation runs. Can't set * close after this code block since by then the connection will have been returned to the pool and may have * been borrowed by another thread. Therefore, the close flag is set in passivate(). */ if (isUnderlyingConnectionClosed)
        {
            // Abnormal close: underlying connection closed unexpectedly, so we // must destroy this proxy try
            {
                pool.invalidateObject(this);
            }
            catch (final IllegalStateException e)
            {
                // pool is closed, so close the connection passivate();
                getInnermostDelegate().close();
            }
            catch (final Exception e)
            {
                throw new SQLException("Cannot close connection (invalidating pooled object failed)", e);
            }
        }
        else
        {
            // Normal close: underlying connection is still open, so we // simply need to return this proxy to the pool try
            {
                pool.returnObject(this);
            }
            catch (final IllegalStateException e)
            {
                // pool is closed, so close the connection passivate();
                getInnermostDelegate().close();
            }
            catch (final SQLException | RuntimeException e)
            {
                throw e;
            }
            catch (final Exception e)
            {
                throw new SQLException("Cannot close connection (return to pool failed)", e);
            }
        }
    }
    finally
    {
        lock.unlock();
    }
}
