void testSharedTransactionConversion() throws Exception  {
    try (DelegatingConnection<?> connectionA = (DelegatingConnection<?>) newConnection();
    DelegatingConnection<?> connectionB = (DelegatingConnection<?>) newConnection())
    {
        // in a transaction the inner connections should be equal assertNotEquals(connectionA, connectionB);
        assertNotEquals(connectionB, connectionA);
        assertTrue(connectionA.innermostDelegateEquals(connectionB.getInnermostDelegate()));
        assertTrue(connectionB.innermostDelegateEquals(connectionA.getInnermostDelegate()));
        transactionManager.commit();
        // use the connection so it adjusts to the completed transaction connectionA.getAutoCommit();
        connectionB.getAutoCommit();
        // no there is no transaction so inner connections should not be equal assertNotEquals(connectionA, connectionB);
        assertNotEquals(connectionB, connectionA);
        assertFalse(connectionA.innermostDelegateEquals(connectionB.getInnermostDelegate()));
        assertFalse(connectionB.innermostDelegateEquals(connectionA.getInnermostDelegate()));
        transactionManager.begin();
        // use the connection so it adjusts to the new transaction connectionA.getAutoCommit();
        connectionB.getAutoCommit();
        // back in a transaction so inner connections should be equal again assertNotEquals(connectionA, connectionB);
        assertNotEquals(connectionB, connectionA);
        assertTrue(connectionA.innermostDelegateEquals(connectionB.getInnermostDelegate()));
        assertTrue(connectionB.innermostDelegateEquals(connectionA.getInnermostDelegate()));
    }
}
